import React, { useEffect, Suspense } from 'react';
import { BrowserRouter } from 'react-router-dom';
import AppRoutes from './routes';
import { ApiProvider } from './context/ApiContext';
import { useDispatch, useSelector } from 'react-redux';
import io from "socket.io-client";
import { Logout, UpdateBalance } from './store/reducers/auth';
import { authenticateSockets } from './utils/socket';
import PreLoader from './components/PreLoader';

function App() {
  const dispatch = useDispatch();
  const { user, balance, isLoggedIn, token } = useSelector((store) => store.auth)

  useEffect(() => {
    let socket = io(`${process.env.REACT_APP_API_URL}`);
    if (isLoggedIn) {
      socket = io(`${process.env.REACT_APP_API_URL}`, { query: { auth: token } });
      authenticateSockets(user._id);
      socket.on("logout", () => {
        dispatch(Logout({}));
      });
      socket.on("reload", () => {
        window.location.reload();
      });
      socket.on("balance", (data) => {
        if (!isLoggedIn) return;
        if (data.balance !== balance) {
          dispatch(UpdateBalance(data.balance));
        }
      });

    }
    return () => {
      if (socket) {
        socket.off("logout");
        socket.off("reload");
        socket.off("balance");
      }
    };
  }, [token, balance, isLoggedIn, user, dispatch]);


  return (
    <BrowserRouter>
      <Suspense fallback={<PreLoader />}>
        <ApiProvider>
            <AppRoutes />
        </ApiProvider>
      </Suspense>
    </BrowserRouter>
  );
}

export default App;
